 def list_connections() -> dict[str, object]:
     db_config = DBConfig()
     uri = db_config.get_database_uri()

     db_name = "Unknown"
     dialect = "unknown"
     try:
         if uri:
             from sqlalchemy.engine import make_url

             url = make_url(uri)
             dialect = url.drivername.split("+")[0].lower()
             if dialect in ["sqlite", "duckdb"]:
                 if url.database:
                     import pathlib

                     db_name = pathlib.Path(url.database).name
                 else:
                     db_name = "db.sqlite"
             else:
                 db_name = url.database if url.database else "Unknown"
     except Exception:
         pass

     return {
         "active_uri": uri,
         "db_name": db_name,
         "dialect": dialect,
         "default_sqlite_path": str(db_config.DEFAULT_SQLITE_PATH),
         "config_file": str(db_config.CONFIG_FILE),
     }


 @router.post("/connections")
 def create_connection(payload: NewConnectionRequest) -> dict[str, str]:
     db_config = DBConfig()
     mode = payload.mode.strip().lower()
     value = payload.value.strip()

     if mode == "sqlite_path":
         selected_uri = normalize_sqlite_uri_from_input(value, db_config)
     elif mode == "direct_uri":
         if not value:
             raise HTTPException(status_code=400, detail="URI cannot be empty.")
         selected_uri = value
     else:
         raise HTTPException(status_code=400, detail="Unsupported mode.")

     db_config.set_database_uri(selected_uri)
     return {"active_uri": selected_uri}


