          <div id="propForm" style="display: none;">
            <div class="form-group">
              <label>Description</label>
              <textarea id="propDescription" rows="4"></textarea>
            </div>
            <div class="form-group">
              <label>Aliases (comma separated)</label>
              <input type="text" id="propAliases">
            </div>
            <button class="btn" id="applyPropBtn">Apply</button>
          </div>
        </div>
      </div>
    </div>

    <div id="instructions-tab" class="tab-content">
      <div style="margin-bottom: 1rem;">
        <button class="btn" id="addInstructionBtn">Add Instruction</button>
      </div>
      <div id="instructionsList">
        <!-- Instructions rendered here -->
      </div>
    </div>

    <div id="yaml-tab" class="tab-content">
      <div id="yamlViewer" class="yaml-viewer">YAML output will appear here.</div>
    </div>
  </div>
</div>

<script>
  // State
  let currentProfile = '';
  let baselineData = { models: [], relationships: [] };
  let semanticData = { models: [], relationships: [], instructions: [] };
  let selection = { type: null, table: null, column: null }; // type: 'table' | 'column'

  // DOM Elements
  const profileSelect = document.getElementById("profileSelect");
  const newProfileBtn = document.getElementById("newProfileBtn");
  const saveBtn = document.getElementById("saveBtn");
  const reindexBtn = document.getElementById("reindexBtn");
  const tablesView = document.getElementById("tablesView");
  const propTitle = document.getElementById("propTitle");
  const propForm = document.getElementById("propForm");
  const propDescription = document.getElementById("propDescription");
  const propAliases = document.getElementById("propAliases");
  const applyPropBtn = document.getElementById("applyPropBtn");
  const instructionsList = document.getElementById("instructionsList");
  const addInstructionBtn = document.getElementById("addInstructionBtn");
  const yamlViewer = document.getElementById("yamlViewer");
  const statusMsg = document.getElementById("statusMsg");

  // Tabs logic
  document.querySelectorAll('.tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
      tab.classList.add('active');
      document.getElementById(tab.dataset.target).classList.add('active');

      if (tab.dataset.target === 'yaml-tab') {
        renderYaml();
      }
    });
  });

  async function loadProfiles() {
    try {
      const { profiles } = await fetch("/api/context/profiles").then((r) => r.json());
      profileSelect.innerHTML = '<option value="">Select Profile...</option>';
      profiles.forEach(p => {
        const opt = document.createElement("option");
        opt.value = p;
        opt.textContent = p;
        if (p === currentProfile) opt.selected = true;
        profileSelect.appendChild(opt);
      });
    } catch (err) {
      console.error(err);
    }
  }

  newProfileBtn.addEventListener('click', async () => {
    const name = prompt("Enter new profile name:");
    if (!name) return;
    try {
      await fetch("/api/context/profiles", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ profile_name: name })
      });
      currentProfile = name;
      await loadProfiles();
      loadProfileData(name);
    } catch (err) {
      alert("Error creating profile: " + err);
    }
  });

  profileSelect.addEventListener("change", (e) => {
    currentProfile = e.target.value;
    loadProfileData(currentProfile);
  });

  async function loadProfileData(profile) {
    if (!profile) return;
    try {
      // 1. Fetch baseline
      let baselineYaml = '';
      try {
        const res = await fetch(`/api/context/files/${profile}/_baseline.generated.yaml`);
        if (res.ok) {
          const data = await res.json();
          baselineYaml = data.content;
        }
      } catch (e) {}

      if (baselineYaml) {
        baselineData = jsyaml.load(baselineYaml) || { models: [], relationships: [] };
      } else {
        baselineData = { models: [], relationships: [] };
      }

      // 2. Fetch semantic yaml
      let semYaml = '';
      try {
        const res = await fetch(`/api/context/files/${profile}/${profile}.semantic.yaml`);
        if (res.ok) {
          const data = await res.json();
          semYaml = data.content;
        }
      } catch (e) {}

      if (semYaml) {
        semanticData = jsyaml.load(semYaml) || { models: [], relationships: [], instructions: [] };
      } else {
        semanticData = { models: [], relationships: [], instructions: [] };
      }

      if (!semanticData.models) semanticData.models = [];
      if (!semanticData.instructions) semanticData.instructions = [];

      renderDiagram();
      renderInstructions();
      renderYaml();
    } catch (err) {
      console.error(err);
      alert("Error loading profile data");
    }
  }

  // --- Diagram Logic ---

  function renderDiagram() {
    tablesView.innerHTML = '';
    if (!baselineData.models || baselineData.models.length === 0) {
      tablesView.innerHTML = '<div style="padding: 2rem; color: #666;">No baseline models found. Try reindexing first.</div>';
      return;
    }

    baselineData.models.forEach(model => {
      const card = document.createElement('div');
      card.className = 'table-card';

      const header = document.createElement('div');
      header.className = 'table-header';
      header.textContent = model.name;
      header.onclick = () => selectEntity('table', model.name, null);

      card.appendChild(header);

      if (model.columns) {
        model.columns.forEach(col => {
          const colDiv = document.createElement('div');
          colDiv.className = `table-column ${col.primary_key ? 'pk' : ''}`;

          const nameSpan = document.createElement('span');
          nameSpan.textContent = col.name;
          if (col.primary_key) nameSpan.textContent += ' (PK)';

          const typeSpan = document.createElement('span');
          typeSpan.style.color = '#888';
          typeSpan.textContent = col.type;

          colDiv.appendChild(nameSpan);
          colDiv.appendChild(typeSpan);
          colDiv.onclick = () => selectEntity('column', model.name, col.name);

          card.appendChild(colDiv);
        });
      }

      tablesView.appendChild(card);
    });
  }

  function selectEntity(type, tableName, columnName) {
    selection = { type, table: tableName, column: columnName };
    propForm.style.display = 'block';

    if (type === 'table') {
      propTitle.textContent = `Table: ${tableName}`;
      const semModel = semanticData.models.find(m => m.name === tableName);
      propDescription.value = semModel?.description || '';
      propAliases.value = (semModel?.aliases || []).join(', ');
    } else {
      propTitle.textContent = `Column: ${tableName}.${columnName}`;
      const semModel = semanticData.models.find(m => m.name === tableName);
      const semCol = semModel?.columns?.find(c => c.name === columnName);
      propDescription.value = semCol?.description || '';
      propAliases.value = ''; // columns don't typically have aliases in this schema, but we leave the field
      propAliases.parentElement.style.display = 'none'; // hide aliases for columns
    }
  }

  applyPropBtn.addEventListener('click', () => {
    if (!selection.table) return;

    let semModel = semanticData.models.find(m => m.name === selection.table);
    if (!semModel) {
      semModel = { name: selection.table, columns: [] };
      semanticData.models.push(semModel);
    }

    if (selection.type === 'table') {
      semModel.description = propDescription.value;
      const aliases = propAliases.value.split(',').map(s => s.trim()).filter(s => s);
      if (aliases.length > 0) semModel.aliases = aliases;
      else delete semModel.aliases;
    } else if (selection.type === 'column') {
      if (!semModel.columns) semModel.columns = [];
      let semCol = semModel.columns.find(c => c.name === selection.column);
      if (!semCol) {
        semCol = { name: selection.column };
        semModel.columns.push(semCol);
      }
      semCol.description = propDescription.value;
    }

    renderYaml();
    alert("Property applied to memory! Remember to Save Changes.");
  });

  // --- Instructions Logic ---

  function renderInstructions() {
    instructionsList.innerHTML = '';
    semanticData.instructions.forEach((inst, index) => {
      const card = document.createElement('div');
      card.className = 'instruction-card';
      card.innerHTML = `
        <div class="form-group">
          <label>ID</label>
          <input type="text" value="${inst.id || ''}" onchange="updateInst(${index}, 'id', this.value)">
        </div>
        <div class="form-group">
          <label>Scope</label>
          <input type="text" value="${inst.scope || 'sql'}" onchange="updateInst(${index}, 'scope', this.value)">
        </div>
        <div class="form-group">
          <label>Question / Prompt</label>
          <input type="text" value="${inst.question || ''}" onchange="updateInst(${index}, 'question', this.value)">
        </div>
        <div class="form-group">
          <label>Instruction</label>
          <textarea rows="4" onchange="updateInst(${index}, 'instruction', this.value)">${inst.instruction || ''}</textarea>
        </div>
        <button class="btn btn-secondary" onclick="deleteInst(${index})">Delete</button>
      `;
      instructionsList.appendChild(card);
    });
  }

  window.updateInst = (index, field, value) => {
    semanticData.instructions[index][field] = value;
    renderYaml();
  };

  window.deleteInst = (index) => {
    semanticData.instructions.splice(index, 1);
    renderInstructions();
    renderYaml();
  };

  addInstructionBtn.addEventListener('click', () => {
    semanticData.instructions.push({
      id: `inst_${Date.now()}`,
      scope: 'sql',
      question: '',
      instruction: ''
    });
    renderInstructions();
    renderYaml();
  });

  // --- YAML Output ---

  function generateCleanSemanticData() {
    // Clone
    const cleanData = JSON.parse(JSON.stringify(semanticData));

    // Cleanup empty models/columns
    cleanData.models = cleanData.models.filter(m => {
      if (m.columns) {
        m.columns = m.columns.filter(c => c.description || c.aliases);
        if (m.columns.length === 0) delete m.columns;
      }
      return m.description || m.aliases || m.columns;
    });

    if (baselineData.relationships && baselineData.relationships.length > 0) {
       cleanData.relationships = baselineData.relationships; // Usually we keep the baseline relationships in the semantic file for the reindexer to read easily
    }

    return cleanData;
  }

  function renderYaml() {
    const cleanData = generateCleanSemanticData();
    yamlViewer.textContent = jsyaml.dump(cleanData, { noRefs: true });
  }

  // --- Save / Reindex ---

  saveBtn.addEventListener('click', async () => {
    if (!currentProfile) return alert("Select a profile first.");

    const yamlString = jsyaml.dump(generateCleanSemanticData(), { noRefs: true });

    try {
      const res = await fetch(`/api/context/files/${currentProfile}/${currentProfile}.semantic.yaml`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: yamlString })
      });

      if (res.ok) {
        statusMsg.style.display = 'block';
        setTimeout(() => statusMsg.style.display = 'none', 3000);
      } else {
        const err = await res.json();
        alert("Error saving: " + JSON.stringify(err));
      }
    } catch (err) {
      alert("Error saving: " + err);
    }
  });

  reindexBtn.addEventListener("click", async () => {
    if (!currentProfile) return alert("Select a profile first.");

    try {
      reindexBtn.textContent = 'Reindexing...';
      const res = await fetch("/api/context/reindex", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ semantic_profile: currentProfile }),
      });
      await res.json();
      reindexBtn.textContent = 'Run Reindex';
      alert('Reindex triggered successfully.');
      loadProfileData(currentProfile); // Reload
    } catch (err) {
      reindexBtn.textContent = 'Run Reindex';
      alert("Error: " + err);
    }
  });

  // Init
  loadProfiles();
</script>
{% endblock %}
EOF

