  <!-- Left Sidebar: Profiles -->
  <div class="sidebar">
    <div class="sidebar-header">
      <h3>Profiles</h3>
      <button class="btn-sm" onclick="createNewProfile()">+ New</button>
    </div>
    <div id="profileList"></div>
  </div>

  <!-- Main Content -->
  <div class="main-content">
    <div class="editor-topbar">
      <div class="topbar-left">
        <h3 id="currentProfileName" style="margin: 0; color: #333;">Select a Profile</h3>
        <div class="status-badge" onclick="openConnectionModal()" title="Change database connection">
          <span id="dbDialectBadge" style="width: 8px; height: 8px; border-radius: 50%; background: #ccc; display: inline-block;"></span>
          <span id="dbNameStr">Not Connected</span>
        </div>
      </div>
      <div class="topbar-right">
        <span id="statusMsg" style="color: green; font-size: 0.9em; display: none;">✔ Saved</span>
        <button class="btn-secondary" id="reindexBtn" onclick="runReindex()">Run Reindex (Create Baseline)</button>
        <button class="btn-primary" id="saveBtn" onclick="saveProfileChanges()">Save Changes</button>
      </div>
