    <div class="tabs">
      <div class="tab active" data-target="diagram-tab">Entity Diagram</div>
      <div class="tab" data-target="instructions-tab">Profile Instructions</div>
      <div class="tab" data-target="common-tab">Common Instructions</div>
      <div class="tab" data-target="yaml-tab">YAML Source</div>
    </div>

    <div class="tab-content-container">
      <!-- Diagram Tab -->
      <div id="diagram-tab" class="tab-pane active" style="flex-direction: row;">
        <div class="diagram-scroll-area" id="diagramScrollArea">
          <div class="diagram-canvas" id="diagramCanvas"></div>
        </div>

        <div class="properties-panel" id="propertiesPanel">
          <h3 id="propTitle" style="margin-top: 0;">Properties</h3>
          <p style="color: #666; font-size: 0.85em; margin-bottom: 1rem;">Edit semantic metadata here.</p>

          <div id="propForm">
            <div class="form-group">
              <label>Description</label>
              <textarea id="propDescription" rows="4"></textarea>
            </div>
            <div class="form-group" id="propAliasesGroup">
              <label>Aliases (comma separated)</label>
              <input type="text" id="propAliases">
            </div>
            <!-- Additional fields for relationships could go here -->
            <button class="btn-primary" style="width: 100%; margin-top: 1rem;" onclick="applyProperties()">Apply to Diagram</button>
