          <!-- File List -->
          <div style="width: 250px; border-right: 1px solid #eee; padding-right: 1rem; overflow-y: auto;">
            <h4 style="margin-top: 0;">Common Files</h4>
            <div id="commonFilesList"></div>
          </div>
          <!-- Editor -->
          <div style="flex: 1; display: none; flex-direction: column;" id="commonEditorContainer">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
              <h4 id="commonEditorTitle" style="margin: 0;">Editing</h4>
              <div>
                <button class="btn-secondary" onclick="addCommonInstruction()">+ Add Rule</button>
                <button class="btn-primary" onclick="saveCommonFile()">Save File</button>
