  <div class="modal-content" onclick="event.stopPropagation()">
    <button class="modal-close" onclick="closeConnectionModal()">&times;</button>
    <h2 style="margin-top: 0;">Connect to Database</h2>
    <p style="font-size: 0.9em; color: #555; margin-bottom: 1rem;">Connect to a database to generate a baseline template via Reindex.</p>

    <div id="connMenu">
      <button class="conn-menu-btn" onclick="showForm('sqlite')">SQLite file path</button>
      <button class="conn-menu-btn" onclick="showForm('docker')">Docker container</button>
      <button class="conn-menu-btn" onclick="showForm('uri')">Direct URI</button>
