      <button class="btn-primary" onclick="submitConnection('sqlite_path', document.getElementById('sqliteInput').value)">Connect</button>
    </div>

    <div id="formDocker" class="conn-form">
      <button class="back-btn" onclick="showMenu()">&larr; Back</button>
