     resetErrors();
     const origText = btnObj.textContent;
     btnObj.textContent = "Connecting...";
     btnObj.disabled = true;

     try {
       const res = await fetch('/api/connections', { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({mode, value}) });
       if (res.ok) {
         closeConnectionModal(); 
