       } else {
         const errId = mode === 'sqlite_path' ? 'errSqlite' : 'errUri';
         document.getElementById(errId).style.display = "block";
       }
     } catch(e) {
       const errId = mode === 'sqlite_path' ? 'errSqlite' : 'errUri';
       document.getElementById(errId).style.display = "block";
     } finally {
       btnObj.textContent = origText;
       btnObj.disabled = false;
     }
   }

