    currentProfile = name;
    document.getElementById('currentProfileName').textContent = `Profile: ${name}`;
    loadProfiles(); 

    // Reset canvas and keep SVG overlay alive
    Array.from(diagramCanvas.children).forEach(child => {
        if(child.tagName.toLowerCase() !== 'svg') child.remove();
    });
    svgGroup.innerHTML = '';
    closeProperties();

    try {
      let bRes = await fetch(`/api/context/files/${name}/_baseline.generated.yaml`);
      if (bRes.ok) { baselineData = jsyaml.load((await bRes.json()).content) || { models: [], relationships: [] }; } 
      else { baselineData = { models: [], relationships: [] }; }

      let filesRes = await fetch(`/api/context/files/${name}`);
      let filesData = await filesRes.json();
      let semanticFile = filesData.files.find(f => f.endsWith('.yaml') && !f.startsWith('_'));

      if (semanticFile) {
        let sRes = await fetch(`/api/context/files/${name}/${semanticFile}`);
        if (sRes.ok) semanticData = jsyaml.load((await sRes.json()).content) || { models: [], relationships: [], instructions: [] };
        else semanticData = { models: [], relationships: [], instructions: [] }; 
      } else { semanticData = { models: [], relationships: [], instructions: [] }; }

      if (!semanticData.models) semanticData.models = [];
      if (!semanticData.relationships) semanticData.relationships = [];
      if (!semanticData.instructions) semanticData.instructions = [];

      renderDiagram();
      renderInstructions();
      renderYaml();
    } catch (e) { console.error(e); }
  }

  function renderDiagram() {
    svgGroup.innerHTML = '';

    if (!baselineData.models || baselineData.models.length === 0) {
      const err = document.createElement('div');
      err.style.padding = '2rem'; err.style.color = '#888';
      err.textContent = 'No baseline models. Please connect to a database and Run Reindex.';
      diagramCanvas.appendChild(err);
      return;
    }

    let x = 50, y = 50, rowMaxH = 0;

    baselineData.models.forEach(model => {
      const card = document.createElement('div');
      card.className = 'table-card';
      card.style.left = x + 'px';
      card.style.top = y + 'px';
      card.id = `table-${model.name}`;

      const header = document.createElement('div');
      header.className = 'table-header';
      header.textContent = model.name;
      header.onclick = (e) => { e.stopPropagation(); selectEntity('table', model.name); };
      card.appendChild(header);

      if (model.columns) {
        model.columns.forEach(col => {
          const colDiv = document.createElement('div');
          colDiv.className = `table-column ${col.primary_key ? 'pk' : ''}`;
          colDiv.id = `col-${model.name}-${col.name}`;
          colDiv.innerHTML = `<span>${col.name} ${col.primary_key?'🔑':''}</span><span style="color:#888;">${col.type.split('(')[0]}</span>`;
          colDiv.onclick = (e) => { e.stopPropagation(); selectEntity('column', col.name, model.name); };
          card.appendChild(colDiv);
        });
      }

      diagramCanvas.appendChild(card);

      x += 280;
      rowMaxH = Math.max(rowMaxH, card.offsetHeight);
      if (x > 1200) { x = 50; y += rowMaxH + 50; rowMaxH = 0; }
    });

    // Draw relationships using Native SVG logic mapping exactly to relative offsets!
    setTimeout(() => {
      if (baselineData.relationships) {
        baselineData.relationships.forEach((rel, index) => {
          const fromCol = document.getElementById(`col-${rel.from_model}-${rel.join.from_column}`);
          const toCol = document.getElementById(`col-${rel.to_model}-${rel.join.to_column}`);

          if (fromCol && toCol) {
            const fromCard = fromCol.parentElement;
            const toCard = toCol.parentElement;

            // Compute precise center-points vertically, and left/right horizontally relative to the canvas
            const x1 = fromCard.offsetLeft + fromCard.offsetWidth; // Right edge of from_card
            const y1 = fromCard.offsetTop + fromCol.offsetTop + (fromCol.offsetHeight / 2);

            const x2 = toCard.offsetLeft; // Left edge of to_card
            const y2 = toCard.offsetTop + toCol.offsetTop + (toCol.offsetHeight / 2);

            // Generate Bezier Curve
            const controlOffset = Math.abs(x2 - x1) * 0.5 + 20;
            const pathData = `M ${x1} ${y1} C ${x1 + controlOffset} ${y1}, ${x2 - controlOffset} ${y2}, ${x2} ${y2}`;

            // Visual line
            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            path.setAttribute('d', pathData);
            path.setAttribute('fill', 'none');
            path.setAttribute('stroke', '#adb5bd');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('marker-end', 'url(#arrow)');

            // Thick invisible line for easy clicking/hovering
            const hitPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            hitPath.setAttribute('d', pathData);
            hitPath.setAttribute('fill', 'none');
            hitPath.setAttribute('stroke', 'transparent');
            hitPath.setAttribute('stroke-width', '15');
            hitPath.style.pointerEvents = 'stroke';
            hitPath.style.cursor = 'pointer';

            const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
            g.appendChild(path);
            g.appendChild(hitPath);

            g.addEventListener('mouseenter', () => { path.setAttribute('stroke', '#0066cc'); path.setAttribute('stroke-width', '3'); path.setAttribute('marker-end', 'url(#arrow-hover)'); });
            g.addEventListener('mouseleave', () => { path.setAttribute('stroke', '#adb5bd'); path.setAttribute('stroke-width', '2'); path.setAttribute('marker-end', 'url(#arrow)'); });

            g.onclick = (e) => {
              e.stopPropagation();
              selectEntity('relation', null, null, index, rel);
            };

            svgGroup.appendChild(g);
          }
        });
      }
    }, 100);
  }

  function selectEntity(type, entityId, parentId = null, relIndex = null, relData = null) {
    selection = { type, entityId, parentId, relIndex };
    document.querySelectorAll('.table-card').forEach(c => c.classList.remove('selected'));

    propertiesPanel.classList.add('active');
    document.getElementById('propStandardFields').style.display = 'none';
    document.getElementById('propRelFields').style.display = 'none';

    if (type === 'table') {
      document.getElementById(`table-${entityId}`)?.classList.add('selected');
      document.getElementById('propTitle').textContent = `Table: ${entityId}`;
      document.getElementById('propSubtitle').textContent = "Edit table details.";
      document.getElementById('propStandardFields').style.display = 'block';
      document.getElementById('propAliasesGroup').style.display = 'block';

      const semModel = semanticData.models.find(m => m.name === entityId);
      document.getElementById('propDescription').value = semModel?.description || '';
      document.getElementById('propAliases').value = (semModel?.aliases || []).join(', ');

    } else if (type === 'column') {
      document.getElementById(`table-${parentId}`)?.classList.add('selected');
      document.getElementById('propTitle').textContent = `Column: ${entityId}`;
      document.getElementById('propSubtitle').textContent = `Belongs to ${parentId}.`;
      document.getElementById('propStandardFields').style.display = 'block';
      document.getElementById('propAliasesGroup').style.display = 'none';

      const semModel = semanticData.models.find(m => m.name === parentId);
      const semCol = semModel?.columns?.find(c => c.name === entityId);
      document.getElementById('propDescription').value = semCol?.description || '';

    } else if (type === 'relation') {
      document.getElementById('propTitle').textContent = `Relationship`;
      document.getElementById('propSubtitle').textContent = `${relData.from_model} \u2192 ${relData.to_model}`;
      document.getElementById('propRelFields').style.display = 'block';

      const semRel = semanticData.relationships?.find(r => r.from_model === relData.from_model && r.to_model === relData.to_model && r.join.from_column === relData.join.from_column) || relData;
      document.getElementById('propRelType').value = semRel.type || 'many_to_one';
      document.getElementById('propRelDescription').value = semRel.description || '';
    }
  }

  function applyProperties() {
    if (selection.type === 'table' || selection.type === 'column') {
      let semModel = semanticData.models.find(m => m.name === (selection.type === 'table' ? selection.entityId : selection.parentId));
      if (!semModel) { semModel = { name: (selection.type === 'table' ? selection.entityId : selection.parentId), columns: [] }; semanticData.models.push(semModel); }

      if (selection.type === 'table') {
        semModel.description = document.getElementById('propDescription').value;
        const aliases = document.getElementById('propAliases').value.split(',').map(s => s.trim()).filter(s => s);
        if (aliases.length > 0) semModel.aliases = aliases; else delete semModel.aliases;
      } else {
        if (!semModel.columns) semModel.columns = [];
        let semCol = semModel.columns.find(c => c.name === selection.entityId);
        if (!semCol) { semCol = { name: selection.entityId }; semModel.columns.push(semCol); }
        semCol.description = document.getElementById('propDescription').value;
      }
    } else if (selection.type === 'relation') {
      const baseRel = baselineData.relationships[selection.relIndex];
      if (!semanticData.relationships) semanticData.relationships = [];
      let semRel = semanticData.relationships.find(r => r.from_model === baseRel.from_model && r.to_model === baseRel.to_model && r.join.from_column === baseRel.join.from_column);

      if (!semRel) { semRel = JSON.parse(JSON.stringify(baseRel)); semanticData.relationships.push(semRel); }
      semRel.type = document.getElementById('propRelType').value;
      semRel.description = document.getElementById('propRelDescription').value;
    }

    renderYaml();
    const msg = document.getElementById('statusMsg');
    msg.textContent = '✔ Property Applied';
    msg.style.display = 'inline'; setTimeout(() => msg.style.display='none', 2000);
  }

  function renderInstructions() {
    const list = document.getElementById('instructionsList');
    list.innerHTML = '';
    semanticData.instructions.forEach((inst, idx) => {
      list.innerHTML += `
        <div class="instruction-card">
          <div class="form-group"><label>ID</label><input type="text" value="${inst.id||''}" onchange="updateInst(${idx}, 'id', this.value)"></div>
          <div class="form-group"><label>Question</label><input type="text" value="${inst.question||''}" onchange="updateInst(${idx}, 'question', this.value)"></div>
          <div class="form-group"><label>Instruction</label><textarea rows="3" onchange="updateInst(${idx}, 'instruction', this.value)">${inst.instruction||''}</textarea></div>
          <button class="btn-sm" style="background:#dc3545;" onclick="delInst(${idx})">Delete</button>
        </div>
      `;
    });
  }

  window.updateInst = (idx, field, val) => semanticData.instructions[idx][field] = val;
  window.delInst = (idx) => { semanticData.instructions.splice(idx, 1); renderInstructions(); };
  window.addInstruction = () => { semanticData.instructions.push({ id: `rule_${Date.now()}`, scope: 'sql', question: '', instruction: '' }); renderInstructions(); };

  function getCleanSemantic() {
    const clean = JSON.parse(JSON.stringify(semanticData));
    clean.models = clean.models.filter(m => {
      if (m.columns) { m.columns = m.columns.filter(c => c.description || c.aliases); if (m.columns.length === 0) delete m.columns; }
      return m.description || m.aliases || m.columns;
    });

    if (clean.relationships) {
      clean.relationships = clean.relationships.filter(r => r.description);
      if (clean.relationships.length === 0) delete clean.relationships;
    }

    if (baselineData.relationships && baselineData.relationships.length > 0) {
      const mergedRels = JSON.parse(JSON.stringify(baselineData.relationships));
      if (clean.relationships) {
        clean.relationships.forEach(sr => {
          let mr = mergedRels.find(r => r.from_model === sr.from_model && r.to_model === sr.to_model && r.join.from_column === sr.join.from_column);
          if (mr) { mr.type = sr.type; mr.description = sr.description; }
        });
      }
      clean.relationships = mergedRels;
    }
    return clean;
  }

  function renderYaml() { document.getElementById('yamlViewer').textContent = jsyaml.dump(getCleanSemantic(), { noRefs: true }); }

  async function saveProfileChanges() {
    if (!currentProfile) return alert("Select a profile.");
    const content = jsyaml.dump(getCleanSemantic(), { noRefs: true });
    try {
      const res = await fetch(`/api/context/files/${currentProfile}/${currentProfile}.semantic.yaml`, {
        method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content })
      });
      if (res.ok) {
        const msg = document.getElementById('statusMsg');
        msg.textContent = '✔ Profile Saved';
        msg.style.display = 'inline'; setTimeout(() => msg.style.display='none', 3000);
      }
    } catch(e) { alert(e); }
  }

  async function runReindex() {
    if (!currentProfile) return alert("Select a profile.");
    try {
      document.getElementById('reindexBtn').textContent = 'Reindexing...';
      const res = await fetch('/api/context/reindex', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ semantic_profile: currentProfile }) });
      document.getElementById('reindexBtn').textContent = 'Run Reindex (Create Template)';
      if (res.ok) { alert("Template baseline generated successfully"); selectProfile(currentProfile); }
      else alert("Reindex failed: " + (await res.json()).detail || "Unknown error");
    } catch(e) { document.getElementById('reindexBtn').textContent = 'Run Reindex (Create Template)'; alert(e); }
  }

  async function loadCommonFiles() {
    try {
      const res = await fetch('/api/context/files/common');
      const list = document.getElementById('commonFilesList');
      list.innerHTML = '';
      (await res.json()).files.forEach(f => {
        const div = document.createElement('div');
        div.className = 'instruction-card common-file';
        div.textContent = f;
        div.onclick = () => selectCommonFile(f);
        list.appendChild(div);
      });
    } catch (e) { console.error(e); }
  }

  async function selectCommonFile(fileName) {
    currentCommonFile = fileName;
    document.getElementById('commonEditorContainer').style.display = 'flex';
    document.getElementById('commonEditorTitle').textContent = `Editing: ${fileName}`;
    try {
      const res = await fetch(`/api/context/files/common/${fileName}`);
      commonFileData = jsyaml.load((await res.json()).content) || { instructions: [] };
      if (!commonFileData.instructions) commonFileData.instructions = [];
      renderCommonInstructions();
    } catch(e) { console.error(e); }
  }

  function renderCommonInstructions() {
    const list = document.getElementById('commonInstructionsList');
    list.innerHTML = '';
    commonFileData.instructions.forEach((inst, idx) => {
      list.innerHTML += `
        <div class="instruction-card">
          <div class="form-group"><label>ID</label><input type="text" value="${inst.id||''}" onchange="updateCInst(${idx}, 'id', this.value)"></div>
          <div class="form-group"><label>Scope</label><input type="text" value="${inst.scope||'sql'}" onchange="updateCInst(${idx}, 'scope', this.value)"></div>
          <div class="form-group"><label>Instruction</label><textarea rows="3" onchange="updateCInst(${idx}, 'instruction', this.value)">${inst.instruction||''}</textarea></div>
          <button class="btn-sm" style="background:#dc3545;" onclick="delCInst(${idx})">Delete</button>
        </div>
      `;
    });
  }

  window.updateCInst = (idx, field, val) => commonFileData.instructions[idx][field] = val;
  window.delCInst = (idx) => { commonFileData.instructions.splice(idx, 1); renderCommonInstructions(); };
  window.addCommonInstruction = () => { commonFileData.instructions.push({ id: `common_${Date.now()}`, scope: 'sql', instruction: '' }); renderCommonInstructions(); };

  async function saveCommonFile() {
    try {
      const res = await fetch(`/api/context/files/common/${currentCommonFile}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content: jsyaml.dump(commonFileData, { noRefs: true }) }) });
      if (res.ok) alert("Common file saved.");
    } catch(e) { alert(e); }
  }

  const connModal = document.getElementById("connModal");
  function openConnectionModal() { connModal.style.display = "flex"; showMenu(); }
  function closeConnectionModal() { connModal.style.display = "none"; resetErrors(); }
  function closeModal(e) { if (e.target === connModal) closeConnectionModal(); }
  function resetErrors() { ['errSqlite', 'errUri', 'errDocker'].forEach(id => document.getElementById(id).style.display = "none"); }
  function hideAllForms() { ["connMenu", "formSqlite", "formDocker", "formUri"].forEach(id => document.getElementById(id).style.display = "none"); resetErrors(); }
  function showMenu() { hideAllForms(); document.getElementById("connMenu").style.display = "block"; }

  function showForm(type) {
    hideAllForms();
    if (type === 'sqlite') {
      document.getElementById("formSqlite").style.display = "flex";
      fetch('/api/connections').then(res => res.json()).then(data => {
        if (data && data.default_sqlite_path) {
          const inp = document.getElementById("sqliteInput");
          if(!inp.value) inp.value = data.default_sqlite_path;
        }
      }).catch(()=>{});
    } else if (type === 'uri') { document.getElementById("formUri").style.display = "flex"; } 
    else if (type === 'docker') {
      document.getElementById("formDocker").style.display = "flex"; document.getElementById("dockerLoading").style.display = "block";
      fetch('/api/connections/docker').then(res => res.json()).then(data => {
        document.getElementById("dockerLoading").style.display = "none";
        const list = document.getElementById("dockerList");
        if (data.docker_status !== "available") { list.innerHTML = `<p style="color:red">Docker unavailable</p>`; return; }
        const connectable = data.containers.filter(c => c.connectable && c.running);
        if (connectable.length === 0) { list.innerHTML = "<p>No containers.</p>"; return; }
        list.innerHTML = connectable.map(c => `<div class="docker-item" onclick="activateDocker('${c.id}')"><strong>${c.name}</strong><br><small>${c.db_type} | ${c.database}</small></div>`).join('');
      }).catch(()=>{});
    }
  }

  async function submitConnection(mode, value, btnObj) {
    resetErrors();
    const origText = btnObj.textContent; btnObj.textContent = "Connecting..."; btnObj.disabled = true;
    try {
      const res = await fetch('/api/connections', { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({mode, value}) });
      if (res.ok) { closeConnectionModal(); loadConnectionStatus(); } 
      else document.getElementById(mode === 'sqlite_path' ? 'errSqlite' : 'errUri').style.display = "block";
    } catch(e) { document.getElementById(mode === 'sqlite_path' ? 'errSqlite' : 'errUri').style.display = "block"; } 
    finally { btnObj.textContent = origText; btnObj.disabled = false; }
  }

  async function activateDocker(id) {
    resetErrors();
    try {
      const res = await fetch(`/api/connections/docker/${id}/activate`, { method: 'POST' });
      if (res.ok) { closeConnectionModal(); loadConnectionStatus(); } else document.getElementById("errDocker").style.display = "block";
    } catch(e) { document.getElementById("errDocker").style.display = "block"; }
  }

  async function loadConnectionStatus() {
    try {
      const res = await fetch('/api/connections');
      const data = await res.json();
      document.getElementById("dbNameStr").textContent = data.db_name || "Unknown";
      const badge = document.getElementById("dbDialectBadge");
      const dialect = data.dialect || "unknown";
      if (dialect.includes("postgres")) badge.style.backgroundColor = "#336791";
      else if (dialect.includes("sqlite")) badge.style.backgroundColor = "#003B57";
      else if (dialect.includes("mysql")) badge.style.backgroundColor = "#00758F";
      else badge.style.backgroundColor = "#555";
    } catch(e) {}
  }
</script>
{% endblock %}''')

